int count = 0;
CGAL::Bbox_3 cgalBox(b.minX(), b.minY(), b.minZ(), b.maxX(), b.maxY(), b.maxZ());

// First get all triangles that intersect the bounding box
std::list<CGALTriangle> intersectedTriangles;
tree.all_intersected_primitives(cgalBox, std::back_inserter(intersectedTriangles));

// Then check each intersected triangle to see if it's completely contained
for (const CGALTriangle& triangle : intersectedTriangles) {
    // Get all three vertices of the triangle
    const CGALPoint& p1 = triangle[0];
    const CGALPoint& p2 = triangle[1];
    const CGALPoint& p3 = triangle[2];

    // Check if all vertices are inside the bounding box
    if (b.isInside(p1.x(), p1.y(), p1.z()) &&
        b.isInside(p2.x(), p2.y(), p2.z()) &&
        b.isInside(p3.x(), p3.y(), p3.z())) {
        count++;
    }
}
return count;

